import type { PackageName } from "./versions.js";

import { VERSIONS } from "./versions.js";

export interface ImportSpec {
  default?: string;
  from: string;
  named?: readonly string[];
  sideEffect?: boolean;
  types?: readonly string[];
}

export type EnvKind = "enum" | "host" | "int" | "port" | "secret" | "string" | "url";

export interface EnvVar {
  comment?: string;
  /** Value written to template.env (secrets are left empty and generated by the secrets script). */
  example: string;
  key: string;
  kind: EnvKind;
  optional?: boolean;
  /** Value used by the generated test setup. */
  testValue?: string;
  values?: readonly string[];
}

/** Pieces of `src/app.module.ts`. */
export interface AppModuleParts {
  controllers: string[];
  imports: ImportSpec[];
  modules: string[];
  providers: string[];
}

/** Pieces of `src/main.setup.ts` (the HTTP bootstrap shared by main.ts and e2e tests). */
export interface MainParts {
  /** Expression passed as the adapter argument of `NestFactory.create`. */
  adapter?: string;
  /** Type argument of `NestFactory.create<...>()`. */
  appType: string;
  /** Statements in main.ts between creating the app and configuring it (e.g. the logger). */
  bootstrap: string[];
  bootstrapImports: ImportSpec[];
  createOptions: string[];
  /** Imports that must run before anything else (e.g. Sentry's instrument file). */
  firstImports: string[];
  imports: ImportSpec[];
  /** Statements run in `configureApplication(app, config)`. */
  setup: string[];
}

export interface ReadmeSection {
  body: string;
  title: string;
}

/**
 * Everything a generated project is made of. Features add to it; renderers turn it into files.
 */
export class Blueprint {
  readonly appModule: AppModuleParts = { controllers: [], imports: [], modules: [], providers: [] };
  readonly dependencies = new Map<string, string>();
  readonly devDependencies = new Map<string, string>();
  readonly env: EnvVar[] = [];
  readonly files = new Map<string, string>();
  readonly main: MainParts = {
    appType: "INestApplication",
    bootstrap: [],
    bootstrapImports: [],
    createOptions: [],
    firstImports: [],
    imports: [],
    setup: [],
  };
  readonly notes: string[] = [];
  readonly readme: ReadmeSection[] = [];
  readonly scripts = new Map<string, string>();

  addFile(path: string, content: string): this {
    this.files.set(path, content.endsWith("\n") ? content : `${content}\n`);
    return this;
  }

  addDependencies(...names: readonly PackageName[]): this {
    for (const name of names) {
      this.dependencies.set(name, VERSIONS[name]);
    }
    return this;
  }

  addDevDependencies(...names: readonly PackageName[]): this {
    for (const name of names) {
      this.devDependencies.set(name, VERSIONS[name]);
    }
    return this;
  }

  addScripts(scripts: Readonly<Record<string, string>>): this {
    for (const [name, command] of Object.entries(scripts)) {
      this.scripts.set(name, command);
    }
    return this;
  }

  addEnv(...vars: readonly EnvVar[]): this {
    for (const variable of vars) {
      if (!this.env.some((existing) => existing.key === variable.key)) {
        this.env.push(variable);
      }
    }
    return this;
  }

  addModule(entry: string, ...imports: readonly ImportSpec[]): this {
    this.appModule.modules.push(entry);
    this.appModule.imports.push(...imports);
    return this;
  }

  addProvider(entry: string, ...imports: readonly ImportSpec[]): this {
    this.appModule.providers.push(entry);
    this.appModule.imports.push(...imports);
    return this;
  }

  addSetup(statement: string, ...imports: readonly ImportSpec[]): this {
    this.main.setup.push(statement);
    this.main.imports.push(...imports);
    return this;
  }

  addBootstrap(statement: string, ...imports: readonly ImportSpec[]): this {
    this.main.bootstrap.push(statement);
    this.main.bootstrapImports.push(...imports);
    return this;
  }

  addReadme(title: string, body: string): this {
    this.readme.push({ body, title });
    return this;
  }

  hasFile(path: string): boolean {
    return this.files.has(path);
  }
}
